<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateAsset\Domain;

use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetUidVO;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetTenantVO;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\Accessor\TemplateAssetTenantAccessor;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetCodeVO;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\Accessor\TemplateAssetCodeAccessor;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetTypeVO;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\Accessor\TemplateAssetTypeAccessor;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetContentVO;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\Accessor\TemplateAssetContentAccessor;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetEnabledVO;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\Accessor\TemplateAssetEnabledAccessor;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\TemplateAssetVersionVO;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\Accessor\TemplateAssetVersionAccessor;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Formula\EnabledCalculator;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Event\TemplateAssetCreateEvent;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Event\TemplateAssetUpdateEvent;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Event\TemplateAssetDeleteEvent;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Event\TemplateAssetEnableEvent;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\Event\TemplateAssetDisableEvent;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Shared\Connector\FileStorage\FileStorageInterface;
use Civi\Lughauth\Shared\Connector\FileStorage\FileStoreKey;

class TemplateAsset extends TemplateAssetRef
{
    use TemplateAssetTenantAccessor;
    use TemplateAssetCodeAccessor;
    use TemplateAssetTypeAccessor;
    use TemplateAssetContentAccessor;
    use TemplateAssetEnabledAccessor;
    use TemplateAssetVersionAccessor;
    private array $recordedEvents = [];

    public function __construct(
        TemplateAssetUidVO|string $uid,
        TemplateAssetTenantVO|TenantRef $tenant,
        TemplateAssetCodeVO|string $code,
        TemplateAssetTypeVO|string $type,
        TemplateAssetContentVO|string $content,
        TemplateAssetEnabledVO|bool|null $enabled = null,
        TemplateAssetVersionVO|int|null $version = null,
    ) {
        parent::__construct($uid);
        $this->_tenant = TemplateAssetTenantVO::from($tenant);
        $this->_code = TemplateAssetCodeVO::from($code);
        $this->_type = TemplateAssetTypeVO::from($type);
        $this->_content = TemplateAssetContentVO::from($content);
        $this->_enabled = null === $enabled ? TemplateAssetEnabledVO::empty() : TemplateAssetEnabledVO::from($enabled);
        $this->_version = null === $version ? TemplateAssetVersionVO::empty() : TemplateAssetVersionVO::from($version);
    }
    public function replace(TemplateAssetAttributes $values): TemplateAsset
    {
        $value = clone $this;
        $value->_tenant = $values->getTenantOrDefault($this->_tenant);
        $value->_code = $values->getCodeOrDefault($this->_code);
        $value->_type = $values->getTypeOrDefault($this->_type);
        $value->_content = $values->getContentOrDefault($this->_content);
        $value->_enabled = $values->getEnabledOrDefault($this->_enabled);
        $value->_version = $values->getVersionOrDefault($this->_version);
        return $value;
    }
    public static function calculatedFields(): array
    {
        return [ 'enabled'];
    }
    public static function create(TemplateAssetAttributes $values): TemplateAsset
    {
        $calculated = clone $values;
        $calculated->enabled(EnabledCalculator::calculateEnabled());
        $value = $calculated->build();
        $value->recordedEvents[] = new TemplateAssetCreateEvent($value);
        return $value;
    }
    public function update(TemplateAssetAttributes $values): TemplateAsset
    {
        $calculated = clone $values;
        $calculated->enabled(EnabledCalculator::calculateEnabled($this));
        $value = $this->replace($calculated);
        $value->recordedEvents[] = new TemplateAssetUpdateEvent($value, $this);
        return $value;
    }
    public function delete(): TemplateAsset
    {
        $value = clone $this;
        $value->recordedEvents[] = new TemplateAssetDeleteEvent($value);
        return $value;
    }
    public function commitContentWith(FileStorageInterface $store): void
    {
        $key = $store->commitContent(new FileStoreKey($this->getContent()));
        $this->_content = TemplateAssetContentVO::fromStored($key->key);
    }
    public function enable(): TemplateAsset
    {
        $value = clone $this;
        $value->_enabled = TemplateAssetEnabledVO::from(true);
        $value->recordedEvents[] = new TemplateAssetEnableEvent($value, original: $this);
        return $value;
    }
    public function disable(): TemplateAsset
    {
        $value = clone $this;
        $value->_enabled = TemplateAssetEnabledVO::from(false);
        $value->recordedEvents[] = new TemplateAssetDisableEvent($value, original: $this);
        return $value;
    }
    public function asPublicJson(): array
    {
        $data = [];
        $data['uid'] = $this->uid();
        $data['tenant'] = [ '$ref' => $this->getTenant()->uid() ];
        $data['code'] = $this->getCode();
        $data['type'] = $this->getType();
        $data['enabled'] = $this->isEnabled();
        $data['version'] = $this->getVersion();
        return $data;
    }
    public function toAttributes(): TemplateAssetAttributes
    {
        return (new TemplateAssetAttributes())
          ->uid($this->uid())
          ->tenant($this->_tenant)
          ->code($this->_code)
          ->type($this->_type)
          ->content($this->_content)
          ->enabled($this->_enabled)
          ->version($this->_version);
    }
    public function getTheEvents(): array
    {
        return [...$this->recordedEvents];
    }
}
